import{_ as t,o as r,c as o,aj as a}from"./chunks/framework.BdtAaXf2.js";const d="/assets/image-20260706150715397.VJx3WVCd.png",e="/assets/image-20260706142113665.BGFX8Eua.png",s="/assets/image-20260706142150951.B_Jjwy04.png",k=JSON.parse('{"title":"WorkBuddy 隐藏技巧：一个设置，积分省一半","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/WorkBuddy 隐藏技巧一个设置，积分省一半/WorkBuddy 隐藏技巧：一个设置，积分省一半.md","filePath":"AI人工智能/WorkBuddy 隐藏技巧一个设置，积分省一半/WorkBuddy 隐藏技巧：一个设置，积分省一半.md","lastUpdated":1783321662000,"__rawMarkdown":"# WorkBuddy 隐藏技巧：一个设置，积分省一半\\n\\n## 前言\\n\\n大家好，我是**万少**，一个深耕鸿蒙和 AI 的技术人。\\n\\n最近腾讯的 AI 工作台 **WorkBuddy** 火了。万少也在深度使用之后，做了一套免费的视频教程，反馈还不错。\\n\\n但录制时间仓促，有一个**特别实用的技巧**忘记录进去了——今天补上。\\n\\n> 还没用过 WorkBuddy 的朋友，可以先看万少的[保姆级入门教程](https://www.bilibili.com/video/BV1PAT16WEtJ/)，5 分钟上手，从零开始。\\n\\n![](assets/image-20260706150715397.png)\\n\\n---\\n\\n## 积分总是不够用？问题出在这里\\n\\n很多小伙伴跟万少反馈：**WorkBuddy 好用是好用，但积分消耗太快了。**\\n\\n聊几个需求，积分就见底了。\\n\\n其实，官方给了一个很简单但容易被忽略的功能——**每个对话窗口，可以单独选择模型**。\\n\\n这才是省积分的关键。\\n\\n---\\n\\n## 怎么用？一句话总结\\n\\n**简单任务用轻量模型，复杂任务用高级模型。**\\n\\n举个例子：\\n\\n- 帮你**写个周报、翻译一段话、整理个表格** → 用基础模型就够了，响应快，积分消耗少\\n- 帮你**分析数据、写代码、做方案** → 切换到高级模型，效果更好，值得花积分\\n\\n操作也很简单，在对话窗口的顶部就能切换：\\n\\n**轻量模型，日常够用：**\\n\\n![](assets/image-20260706142113665.png)\\n\\n**高级模型，硬核任务：**\\n\\n![](assets/image-20260706142150951.png)\\n\\n**关键点：不同的对话窗口可以用不同的模型。** 所以万少建议，你可以按任务类型建不同的对话——日常问答一个窗口，深度创作一个窗口，积分花在刀刃上。\\n\\n---\\n\\n## 万少的实战用法\\n\\n万少平时是这么分的：\\n\\n| 场景 | 模型选择 | 原因 |\\n|------|---------|------|\\n| 查资料、翻译、简单问答 | 基础模型 | 快，省积分 |\\n| 写鸿蒙代码、技术方案 | 高级模型 | 质量要求高 |\\n| 飞书记账、日程整理 | 基础模型 | 简单指令，够用 |\\n| 长文写作、数据分析 | 高级模型 | 需要深度理解 |\\n\\n一个小小的切换习惯，**同样的积分，能多用一倍**。\\n\\n---\\n\\n## 写在最后\\n\\nAI 时代正在带来各行各业的变革。\\n\\n**多了解一些，总归是有好处的。**\\n\\n毕竟，未来的程序员，可能不是写代码最快的那个，而是**最会用 AI 的那个**。\\n\\n---\\n\\n> 关注**万少**，一个既懂鸿蒙又懂 AI 的技术人。\\n>\\n> 这里没有晦涩的理论，只有**用得上的实战技巧**。\\n>\\n> 公众号会持续分享 AI 提效、鸿蒙开发、工具评测等内容，关注我，一起跟上这个时代。\\n"}'),p={name:"AI人工智能/WorkBuddy 隐藏技巧一个设置，积分省一半/WorkBuddy 隐藏技巧：一个设置，积分省一半.md"};function i(l,n,g,h,_,u){return r(),o("div",null,[...n[0]||(n[0]=[a("",36)])])}const m=t(p,[["render",i]]);export{k as __pageData,m as default};
